-- FAQ de la Tecnicatura Superior en Programación (id 217): de 3 a 9 preguntas.
-- Aprobadas por el usuario el 28/11/2026. Fuentes: ficha oficial de Teclab
-- (teclab.edu.ar/carrera/tecnico-superior-en-programacion), plan en D1 y
-- carreras/teclab/articulaciones-teclab.json. Pendiente 3 de PENDIENTES.md.
-- El WHERE exige el JSON actual: si alguien lo cambió, no escribe nada.
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Programación?","respuesta":"La formación abarca lógica de programación, bases de datos, desarrollo web e integración de sistemas. Aprendés a construir aplicaciones y a conectar sus interfaces con los servicios que procesan y almacenan la información."},{"pregunta":"¿Qué significa desarrollo Full Stack en Programación?","respuesta":"Es el trabajo con las dos partes de una aplicación: la interfaz que utiliza la persona y la lógica que funciona detrás. La carrera combina contenidos de front-end, back-end y bases de datos para desarrollar soluciones digitales."},{"pregunta":"¿Qué tareas puede realizar un técnico en Programación?","respuesta":"Puede participar en la creación y mantenimiento de aplicaciones web y móviles, integrar sistemas y organizar bases de datos. Estas tareas forman parte de proyectos de desarrollo de software para personas y organizaciones."},{"pregunta":"¿Cuánto dura la Tecnicatura en Programación y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres. Se cursa 100% online, con clases en vivo que quedan grabadas, así que podés verlas cuando te quede cómodo."},{"pregunta":"¿Qué título obtengo al terminar?","respuesta":"El de Técnico Superior en Programación, un título oficial con acreditación nacional. Al completar el primer año obtenés además el certificado intermedio de Auxiliar en Programación."},{"pregunta":"¿Necesito saber programar para empezar?","respuesta":"No. La carrera arranca desde cero, con Lógica de programación en el primer cuatrimestre, y avanza paso a paso con el acompañamiento de tutores y docentes."},{"pregunta":"¿Cómo sumo experiencia práctica antes de recibirme?","respuesta":"Desde el comienzo, las actividades se plantean como desafíos de programación. En el último cuatrimestre hacés Práctica profesional I y II, donde aplicás desarrollo web, bases de datos y pruebas de software a situaciones reales de trabajo."},{"pregunta":"¿Qué relación tiene la carrera con Avenga?","respuesta":"El plan de estudios se diseñó junto a Avenga, una empresa de desarrollo de software, para que los contenidos trabajen con herramientas y metodologías que se usan en la industria."},{"pregunta":"¿Puedo seguir estudiando en Universidad Siglo 21 después?","respuesta":"Sí. El título articula con Ingeniería en Software y con la Licenciatura en Informática de Universidad Siglo 21. Podés ver qué materias se reconocen en el simulador de equivalencias de Siglo 21."}]}]' WHERE id = 217 AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Programación?","respuesta":"La formación abarca lógica de programación, bases de datos, desarrollo web e integración de sistemas. Aprendés a construir aplicaciones y a conectar sus interfaces con los servicios que procesan y almacenan la información."},{"pregunta":"¿Qué significa desarrollo Full Stack en Programación?","respuesta":"Es el trabajo con las dos partes de una aplicación: la interfaz que utiliza la persona y la lógica que funciona detrás. La carrera combina contenidos de front-end, back-end y bases de datos para desarrollar soluciones digitales."},{"pregunta":"¿Qué tareas puede realizar un técnico en Programación?","respuesta":"Puede participar en la creación y mantenimiento de aplicaciones web y móviles, integrar sistemas y organizar bases de datos. Estas tareas forman parte de proyectos de desarrollo de software para personas y organizaciones."}]}]';
